
CREATE TABLE "FASTSQLORDER" ("ID" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY NOT NULL, "CUSTOMERNAME" VARCHAR2(64 CHAR) NULL, "CUSTOMERID" NUMBER(10) NOT NULL, "AMOUNT" NUMBER(18,4) NOT NULL, "STATE" NUMBER(10) NOT NULL, "CREATEDAT" TIMESTAMP(3) NOT NULL, "PAIDAT" TIMESTAMP(3) NULL, "NOTE" CLOB NULL, CONSTRAINT "PK_FASTSQLORDER" PRIMARY KEY ("ID")) ; CREATE INDEX "IX_FASTSQLORDER_CREATEDAT" ON "FASTSQLORDER" ( "CREATEDAT" ASC )
